// Las tres tiendas peruanas (empresas distintas) que scrapea el agente.
// Usan la API pública de catálogo de VTEX: /api/catalog_system/pub/products/search
// Caso 2: cambia una url_catalogo por un dominio inexistente para simular una tienda caída.
const busqueda = '/api/catalog_system/pub/products/search?ft=zapatillas&O=OrderByTopSaleDESC&_from=0&_to=19';
return [
  { tienda: 'Footloose', empresa: 'Footloose',                 dominio: 'https://www.footloose.pe' },
  { tienda: 'Oechsle',   empresa: 'Oechsle (Intercorp)',       dominio: 'https://www.oechsle.pe' },
  { tienda: 'Estilos',   empresa: 'Estilos',                   dominio: 'https://www.estilos.com.pe' },
].map(t => ({ json: { ...t, url_catalogo: t.dominio + busqueda } }));

// Revisa el intento 1 del agente: ¿trajo al menos 10 productos por tienda?
const tiendas = $('Tiendas').all().map(i => i.json);
return $input.all().map((it, i) => {
  const t = tiendas[i];
  const out = String(it.json.output ?? '');
  let n = 0, err = it.json.error ? (it.json.error.message || String(it.json.error)) : null;
  try {
    const m = out.match(/\{[\s\S]*\}/);
    const o = JSON.parse(m ? m[0] : out);
    if (o.error) err = o.error;
    n = Array.isArray(o.productos) ? o.productos.length : 0;
  } catch (e) {
    n = (out.match(/"modelo"/g) || []).length;
  }
  return { json: { ...t, output: out, error_agente: err, productos_intento1: n, completo: n >= 10 } };
});

// Limpia y consolida la salida del agente (requisitos 8, 9 y 10)
const revision = $('Revisar intento').all().map(i => i.json);   // intento 1 del agente
const tiendas = revision;
const salidas = $input.all();
const ahora = new Date();
const fecha = ahora.toLocaleString('sv-SE', { timeZone: 'America/Lima' }).replace(' ', 'T') + '-05:00';

const limpiar = v => String(v ?? '').replace(/\s+/g, ' ').trim();
const limpiarPrecio = v => {
  if (typeof v === 'number') return Math.round(v * 100) / 100;
  let s = String(v ?? '').replace(/S\/|PEN|soles|\s/gi, '');
  if (/,\d{1,2}$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');   // 1.299,90
  else s = s.replace(/,/g, '');                                          // 1,299.90
  return Math.round(parseFloat(s) * 100) / 100;
};

const filas = [];
const vistos = new Set();
const resumen = [];
salidas.forEach((reintento, i) => {
  const t = tiendas[i] ?? { tienda: `Tienda ${i + 1}` };
  // Si el intento 1 ya trajo 10 o más productos se usa ese; si no, el del reintento
  const item = t.completo ? { json: { output: t.output, error: t.error_agente } } : reintento;
  let productos = [];
  let error = null;
  try {
    if (item.json.error) throw new Error(typeof item.json.error === 'string' ? item.json.error : (item.json.error.message || 'Error del agente'));
    const texto = String(item.json.output ?? '');
    const m = texto.match(/\{[\s\S]*\}/);
    let obj;
    try {
      obj = JSON.parse(m ? m[0] : texto);
    } catch (e) {
      // El LLM a veces escribe mal un producto: se rescatan uno por uno y se descartan los rotos
      const sueltos = (texto.match(/\{[^{}]*\}/g) || []).map(t => { try { return JSON.parse(t); } catch { return null; } });
      obj = { productos: sueltos.filter(p => p && p.modelo) };
      if (!obj.productos.length) { const er = texto.match(/"error"\s*:\s*"([^"]+)"/); throw new Error(er ? er[1] : 'Respuesta del agente no es JSON: ' + e.message); }
    }
    if (obj.error) throw new Error(obj.error);
    productos = Array.isArray(obj.productos) ? obj.productos : [];
    if (!productos.length) throw new Error('El agente no devolvió productos');
  } catch (e) {
    error = e.message;
  }
  let n = 0;
  for (const p of productos) {
    const modelo = limpiar(p.modelo);
    const precio = limpiarPrecio(p.precio);
    const url = limpiar(p.url);
    if (!modelo || !Number.isFinite(precio) || precio <= 0) continue;
    const clave = `${t.tienda}|${url || modelo}`.toLowerCase();
    if (vistos.has(clave)) continue;          // sin duplicados
    vistos.add(clave);
    filas.push({
      'Tienda': t.tienda,
      'Marca': limpiar(p.marca),
      'Modelo': modelo,
      'Precio': precio,
      'Moneda': (limpiar(p.moneda) || 'PEN').toUpperCase(),
      'URL': url,
      'Fecha de scrapeo': fecha,
    });
    n++;
  }
  if (!error && n === 0) error = 'Sin productos válidos';
  resumen.push({ tienda: t.tienda, url_catalogo: t.url_catalogo, productos: n, ok: !error, error });
});

const fallidas = resumen.filter(r => !r.ok);
return [{ json: { fecha, total: filas.length, resumen, tiendas_fallidas: fallidas.map(r => r.tienda), filas } }];

