// Prepara el contenido en base64 para subirlo a GitHub (rama data)
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const item = $input.first();
return [{ json: { contenido: buf.toString('base64'), bytes: buf.length }, binary: item.binary }];

// Recupera el Excel (binario) para adjuntarlo al correo
const excel = $('Convertir a Excel').first();
const subida = $input.first().json;
return [{ json: { commit: subida.commit?.html_url ?? null }, binary: excel.binary }];
